def pivotArray(nums, pivot):
    # Separate lists for < pivot, == pivot, and > pivot
    less = []
    equal = []
    greater = []

    for num in nums:
        if num < pivot:
            less.append(num)
        elif num == pivot:
            equal.append(num)
        else:
            greater.append(num)

    # Combine and return the three lists in order
    return less + equal + greater
